"use strict";(self.webpackChunkthe_indian_justice_academy=self.webpackChunkthe_indian_justice_academy||[]).push([["2891"],{3545(e,n,i){i.r(n),i.d(n,{metadata:()=>s,default:()=>h,frontMatter:()=>r,contentTitle:()=>l,toc:()=>d,assets:()=>o});var s=JSON.parse('{"id":"the-advocates-act-1961/K-V-Krishnaswami-Aiyar","title":"K. V. Krishnaswami Aiyar","description":"K. V. Krishnaswami Aiyar","source":"@site/docs/the-advocates-act-1961/KVKrishnaswamiAiyar.md","sourceDirName":"the-advocates-act-1961","slug":"/the-advocates-act-1961/K-V-Krishnaswami-Aiyar","permalink":"/theindianjustice-academy/docs/the-advocates-act-1961/K-V-Krishnaswami-Aiyar","draft":false,"unlisted":false,"editUrl":"#/docs/the-advocates-act-1961/KVKrishnaswamiAiyar.md","tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"id":"K-V-Krishnaswami-Aiyar","title":"K. V. Krishnaswami Aiyar","sidebar_label":"K. V. Krishnaswami Aiyar\'s Professional Conduct and Advocacy","sidebar_position":1},"sidebar":"tutorialSidebar","previous":{"title":"The Advocates Act, 1961","permalink":"/theindianjustice-academy/docs/category/the-advocates-act-1961"},"next":{"title":"Legal Profession in India","permalink":"/theindianjustice-academy/docs/the-advocates-act-1961/legal-profession-in-india"}}'),a=i(4848),t=i(8453);let r={id:"K-V-Krishnaswami-Aiyar",title:"K. V. Krishnaswami Aiyar",sidebar_label:"K. V. Krishnaswami Aiyar's Professional Conduct and Advocacy",sidebar_position:1},l="Professional Conduct and Advocacy",o={},d=[{value:"K. V. Krishnaswami Aiyar",id:"k-v-krishnaswami-aiyar",level:2},{value:"Chapter I: The Legal Profession and Its Responsibilities",id:"chapter-i-the-legal-profession-and-its-responsibilities",level:2},{value:"1. Law as a Great Profession",id:"1-law-as-a-great-profession",level:3},{value:"2. A Learned Profession",id:"2-a-learned-profession",level:3},{value:"3. An Independent Profession",id:"3-an-independent-profession",level:3},{value:"4. Leadership and Social Influence",id:"4-leadership-and-social-influence",level:3},{value:"5. Criticism Against Lawyers",id:"5-criticism-against-lawyers",level:3},{value:"6. Comparison with the Medical Profession",id:"6-comparison-with-the-medical-profession",level:3},{value:"7. Reply to the Charge of Dishonesty",id:"7-reply-to-the-charge-of-dishonesty",level:3},{value:"8. Responsibilities of the Profession",id:"8-responsibilities-of-the-profession",level:3},{value:"Central Message",id:"central-message",level:3},{value:"Chapter II: The Equipment of the Lawyer",id:"chapter-ii-the-equipment-of-the-lawyer",level:2},{value:"1. Legal Learning",id:"1-legal-learning",level:3},{value:"2. Wide Knowledge and Range of Ideas",id:"2-wide-knowledge-and-range-of-ideas",level:3},{value:"3. Moral Excellence",id:"3-moral-excellence",level:3},{value:"4. Industry and Hard Work",id:"4-industry-and-hard-work",level:3},{value:"5. The Seven Lamps of Advocacy",id:"5-the-seven-lamps-of-advocacy",level:3},{value:"6. Tact as an Additional Quality",id:"6-tact-as-an-additional-quality",level:3},{value:"Central Message",id:"central-message-1",level:3},{value:"Chapter III: Hints for Law Studies",id:"chapter-iii-hints-for-law-studies",level:2},{value:"1. Law Is a Vast Science",id:"1-law-is-a-vast-science",level:3},{value:"2. Study Law, Do Not Merely Read It",id:"2-study-law-do-not-merely-read-it",level:3},{value:"3. Repetition and Memory",id:"3-repetition-and-memory",level:3},{value:"4. Make Systematic Notes",id:"4-make-systematic-notes",level:3},{value:"5. Study with an Enquiring Mind",id:"5-study-with-an-enquiring-mind",level:3},{value:"6. Study Through Actual Cases",id:"6-study-through-actual-cases",level:3},{value:"7. Use Leisure for Legal Learning",id:"7-use-leisure-for-legal-learning",level:3},{value:"8. Read Law Reports and Use Legal Language",id:"8-read-law-reports-and-use-legal-language",level:3},{value:"9. Know the Law Library and Law Reports",id:"9-know-the-law-library-and-law-reports",level:3},{value:"10. Important Branches of Law and Procedure",id:"10-important-branches-of-law-and-procedure",level:3},{value:"Central Message",id:"central-message-2",level:3},{value:"Chapter IV: Training Grounds",id:"chapter-iv-training-grounds",level:2},{value:"1. Attend the Chambers of a Senior",id:"1-attend-the-chambers-of-a-senior",level:3},{value:"2. Put Forth the Best Effort",id:"2-put-forth-the-best-effort",level:3},{value:"3. Learn Through Observation and Discussion",id:"3-learn-through-observation-and-discussion",level:3},{value:"4. Show Professional Qualities",id:"4-show-professional-qualities",level:3},{value:"5. The Court-House as a Training Ground",id:"5-the-court-house-as-a-training-ground",level:3},{value:"6. Learn from Trials",id:"6-learn-from-trials",level:3},{value:"7. Use Special Opportunities",id:"7-use-special-opportunities",level:3},{value:"Central Message",id:"central-message-3",level:3},{value:"Chapter V: Meeting Clients",id:"chapter-v-meeting-clients",level:2},{value:"1. Receive the Client with Kindness",id:"1-receive-the-client-with-kindness",level:3},{value:"2. Make Careful Inquiries",id:"2-make-careful-inquiries",level:3},{value:"3. Do Not Believe Everything Blindly",id:"3-do-not-believe-everything-blindly",level:3},{value:"4. Inspire Confidence Through Conduct",id:"4-inspire-confidence-through-conduct",level:3},{value:"5. Offering Opinions and Advice",id:"5-offering-opinions-and-advice",level:3},{value:"6. Fixing the Fee",id:"6-fixing-the-fee",level:3},{value:"7. Treat Poor Clients Fairly",id:"7-treat-poor-clients-fairly",level:3},{value:"Central Message",id:"central-message-4",level:3},{value:"Chapter VI: The Preparation of a Case",id:"chapter-vi-the-preparation-of-a-case",level:2},{value:"1. Form a Clear Plan",id:"1-form-a-clear-plan",level:3},{value:"2. Study the Documents and Investigate the Facts",id:"2-study-the-documents-and-investigate-the-facts",level:3},{value:"3. Study the Law Thoroughly",id:"3-study-the-law-thoroughly",level:3},{value:"4. Prepare for the Trial",id:"4-prepare-for-the-trial",level:3},{value:"5. Prepare the Evidence and Witnesses",id:"5-prepare-the-evidence-and-witnesses",level:3},{value:"6. Prepare for Cross-Examination",id:"6-prepare-for-cross-examination",level:3},{value:"7. Arrange Papers Properly",id:"7-arrange-papers-properly",level:3},{value:"8. Preparation for Appellate Hearings",id:"8-preparation-for-appellate-hearings",level:3},{value:"9. Rehearse and Think Repeatedly",id:"9-rehearse-and-think-repeatedly",level:3}];function c(e){let n={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,t.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"professional-conduct-and-advocacy",children:"Professional Conduct and Advocacy"})}),"\n",(0,a.jsx)(n.h2,{id:"k-v-krishnaswami-aiyar",children:"K. V. Krishnaswami Aiyar"}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"chapter-i-the-legal-profession-and-its-responsibilities",children:"Chapter I: The Legal Profession and Its Responsibilities"}),"\n",(0,a.jsxs)(n.p,{children:["In Chapter I of ",(0,a.jsx)(n.em,{children:"Professional Conduct and Advocacy"}),", K. V. Krishnaswami Aiyar introduces the legal profession and explains its importance, dignity and responsibilities in society. He argues that a lawyer\u2019s role is much greater than merely representing clients in court: the lawyer helps maintain justice, protects rights and contributes to the proper organisation of society."]}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://archive.org/stream/professionalcond029273mbp/professionalcond029273mbp_djvu.txt",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"1-law-as-a-great-profession",children:"1. Law as a Great Profession"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar describes law as one of the greatest and most attractive peaceful professions. It is a controlling and unifying institution because it:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Defines the rights of individuals."}),"\n",(0,a.jsx)(n.li,{children:"Imposes duties and obligations."}),"\n",(0,a.jsx)(n.li,{children:"Provides remedies for wrongs."}),"\n",(0,a.jsx)(n.li,{children:"Maintains order in society."}),"\n",(0,a.jsx)(n.li,{children:"Helps resolve disputes according to established principles."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The legal profession therefore serves both the individual client and the wider community."}),"\n",(0,a.jsx)(n.h3,{id:"2-a-learned-profession",children:"2. A Learned Profession"}),"\n",(0,a.jsx)(n.p,{children:"The legal profession is called a learned profession because it requires knowledge, study and intellectual ability. Law is not simply a collection of rules; it is a science concerned with distinguishing right from wrong and establishing justice."}),"\n",(0,a.jsx)(n.p,{children:"The practice of law develops several important qualities in a lawyer:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Ability to analyse and classify facts."}),"\n",(0,a.jsx)(n.li,{children:"Capacity to understand complicated human relationships."}),"\n",(0,a.jsx)(n.li,{children:"Skill in discovering the motives behind human conduct."}),"\n",(0,a.jsx)(n.li,{children:"Power to present facts and arguments clearly."}),"\n",(0,a.jsx)(n.li,{children:"Ability to deal with difficult and complicated situations."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"According to Aiyar, legal learning should also produce high standards of conduct. A lawyer who possesses knowledge but lacks honesty, judgment and moral character does not truly represent the ideals of the profession."}),"\n",(0,a.jsx)(n.h3,{id:"3-an-independent-profession",children:"3. An Independent Profession"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar considers independence to be one of the most important features of the legal profession. A lawyer must be able to oppose injustice, tyranny and unlawful conduct without fear."}),"\n",(0,a.jsx)(n.p,{children:"The lawyer\u2019s independence is not merely a personal privilege. It is necessary for the protection of justice. If advocates become dependent on powerful clients, political authorities or improper influences, they cannot effectively defend rights or assist the court."}),"\n",(0,a.jsx)(n.p,{children:"This independence gives lawyers a natural position of leadership in public life. Their education, judgment and experience with social problems enable them to guide public opinion and take part in important State services."}),"\n",(0,a.jsx)(n.h3,{id:"4-leadership-and-social-influence",children:"4. Leadership and Social Influence"}),"\n",(0,a.jsx)(n.p,{children:"The legal profession has traditionally produced leaders in public administration, politics and social reform. Aiyar explains that this leadership should not be based merely on the prestige of the profession. It must be earned through:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Ability."}),"\n",(0,a.jsx)(n.li,{children:"Character."}),"\n",(0,a.jsx)(n.li,{children:"Sound judgment."}),"\n",(0,a.jsx)(n.li,{children:"Courage."}),"\n",(0,a.jsx)(n.li,{children:"Independence."}),"\n",(0,a.jsx)(n.li,{children:"Service to justice and society."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A lawyer\u2019s influence creates a corresponding responsibility. The more authority and respect a lawyer enjoys, the greater the duty to use that influence honestly and for lawful purposes."}),"\n",(0,a.jsx)(n.h3,{id:"5-criticism-against-lawyers",children:"5. Criticism Against Lawyers"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar recognises that lawyers are frequently criticised. Some people accuse them of:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Having an unnecessarily prominent position in society."}),"\n",(0,a.jsx)(n.li,{children:"Encouraging disputes and litigation."}),"\n",(0,a.jsx)(n.li,{children:"Being dishonest or untruthful."}),"\n",(0,a.jsx)(n.li,{children:"Increasing social conflict instead of promoting peace."}),"\n",(0,a.jsx)(n.li,{children:"Being an unproductive or economically unnecessary class."}),"\n",(0,a.jsx)(n.li,{children:"Using legal technicalities for personal gain."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The author treats much of this criticism as unfair or exaggerated. Lawyers are often involved in disputes because their professional duty requires them to represent people who are already in conflict. The existence of litigation does not mean that lawyers create every dispute."}),"\n",(0,a.jsx)(n.p,{children:"In a complex society, disagreements concerning property, contracts, family relations, business and public rights are unavoidable. Someone must explain the law, present the evidence and assist the court. The lawyer performs this necessary function."}),"\n",(0,a.jsx)(n.h3,{id:"6-comparison-with-the-medical-profession",children:"6. Comparison with the Medical Profession"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar compares the legal profession with medicine. A doctor deals with physical illness, while a lawyer deals with disputes, rights and social injuries. Just as society needs doctors to protect physical health, it needs lawyers to protect legal rights and maintain the health of its legal system."}),"\n",(0,a.jsx)(n.p,{children:"The lawyer\u2019s work may sometimes appear controversial because it involves opposing parties. Nevertheless, the lawyer\u2019s assistance is essential for the judge to understand the facts, legal principles and competing claims."}),"\n",(0,a.jsx)(n.h3,{id:"7-reply-to-the-charge-of-dishonesty",children:"7. Reply to the Charge of Dishonesty"}),"\n",(0,a.jsx)(n.p,{children:"The author rejects the general accusation that lawyers are naturally dishonest or venal. He accepts that some members of every profession may act improperly, but the misconduct of a few should not be used to condemn the entire profession."}),"\n",(0,a.jsx)(n.p,{children:"A lawyer\u2019s reputation depends on public confidence. Dishonesty by advocates damages not only individual clients but also the administration of justice. Therefore, members of the profession must preserve:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Truthfulness."}),"\n",(0,a.jsx)(n.li,{children:"Honour."}),"\n",(0,a.jsx)(n.li,{children:"Fairness."}),"\n",(0,a.jsx)(n.li,{children:"Independence."}),"\n",(0,a.jsx)(n.li,{children:"Respect for the court."}),"\n",(0,a.jsx)(n.li,{children:"Loyalty to the proper interests of the client."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Aiyar also suggests that the intensity of criticism directed at lawyers is partly a measure of their importance. A profession exercising considerable influence will naturally attract both supporters and critics."}),"\n",(0,a.jsx)(n.h3,{id:"8-responsibilities-of-the-profession",children:"8. Responsibilities of the Profession"}),"\n",(0,a.jsx)(n.p,{children:"The legal profession has responsibilities both inside and outside the courtroom. These include:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Assisting the court in reaching a correct decision."}),"\n",(0,a.jsx)(n.li,{children:"Protecting the lawful interests of clients."}),"\n",(0,a.jsx)(n.li,{children:"Refusing to support fraud or dishonest litigation."}),"\n",(0,a.jsx)(n.li,{children:"Maintaining independence from improper influence."}),"\n",(0,a.jsx)(n.li,{children:"Preserving the dignity and honour of the Bar."}),"\n",(0,a.jsx)(n.li,{children:"Promoting respect for law and justice."}),"\n",(0,a.jsx)(n.li,{children:"Using legal knowledge for the benefit of society."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A lawyer must remember that professional success cannot be measured only by income or the number of cases won. The lawyer is also responsible for maintaining public confidence in the legal system."}),"\n",(0,a.jsx)(n.h3,{id:"central-message",children:"Central Message"}),"\n",(0,a.jsx)(n.p,{children:"The main idea of the chapter is that the legal profession is a noble, learned and independent profession, but its privileges are accompanied by serious responsibilities. A lawyer\u2019s education gives them influence and leadership, yet that influence must be controlled by integrity, courage and devotion to justice."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"chapter-ii-the-equipment-of-the-lawyer",children:"Chapter II: The Equipment of the Lawyer"}),"\n",(0,a.jsxs)(n.p,{children:["In Chapter II of ",(0,a.jsx)(n.em,{children:"Professional Conduct and Advocacy"}),", K. V. Krishnaswami Aiyar explains that a successful lawyer needs more than a law degree or the ability to speak well. The \u201Cequipment\u201D of a lawyer consists of legal learning, broad knowledge, moral character, hard work, practical judgment and tact."]}),"\n",(0,a.jsx)(n.p,{children:"The chapter specifically discusses legal learning, wide-ranging ideas, moral excellence, industry and the Seven Lamps of Advocacy, with tact added as an eighth quality."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://ia801404.us.archive.org/25/items/in.ernet.dli.2015.212338/2015.212338.Professional-Conduct_text.pdf",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"1-legal-learning",children:"1. Legal Learning"}),"\n",(0,a.jsx)(n.p,{children:"The first and most important equipment of a lawyer is accurate and extensive legal learning. A lawyer should not merely memorise legal rules or pass examinations. Examination success alone does not prove that a person can practise law effectively."}),"\n",(0,a.jsx)(n.p,{children:"A lawyer must be able to:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Understand legal principles deeply."}),"\n",(0,a.jsx)(n.li,{children:"Apply the law to changing facts."}),"\n",(0,a.jsx)(n.li,{children:"Locate the correct legal rules."}),"\n",(0,a.jsx)(n.li,{children:"Frame proper questions for investigation."}),"\n",(0,a.jsx)(n.li,{children:"Analyse statutes and judicial decisions."}),"\n",(0,a.jsx)(n.li,{children:"Explain the law clearly to the court and the client."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Legal knowledge should be practical and usable. It must help the advocate identify the real issue in a case and find an appropriate legal solution."}),"\n",(0,a.jsx)(n.h3,{id:"2-wide-knowledge-and-range-of-ideas",children:"2. Wide Knowledge and Range of Ideas"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar states that a lawyer should possess both depth and breadth of knowledge. The advocate must know one subject thoroughly but should also have a general understanding of many other subjects."}),"\n",(0,a.jsx)(n.p,{children:"This wider knowledge is useful because legal disputes arise from every area of life, including:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Business and commerce."}),"\n",(0,a.jsx)(n.li,{children:"Property and family relations."}),"\n",(0,a.jsx)(n.li,{children:"Politics and administration."}),"\n",(0,a.jsx)(n.li,{children:"History and social conditions."}),"\n",(0,a.jsx)(n.li,{children:"Science, technology and human behaviour."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A lawyer who knows only legal rules may fail to understand the facts to which those rules must be applied. General education improves reasoning, conversation, judgment and the ability to understand witnesses and clients."}),"\n",(0,a.jsx)(n.h3,{id:"3-moral-excellence",children:"3. Moral Excellence"}),"\n",(0,a.jsx)(n.p,{children:"Legal learning without moral character can become dangerous. Aiyar therefore gives great importance to honesty, integrity and moral excellence."}),"\n",(0,a.jsx)(n.p,{children:"A lawyer must be:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Truthful in dealing with the court."}),"\n",(0,a.jsx)(n.li,{children:"Fair to the client and the opponent."}),"\n",(0,a.jsx)(n.li,{children:"Loyal to professional duties."}),"\n",(0,a.jsx)(n.li,{children:"Free from corrupt motives."}),"\n",(0,a.jsx)(n.li,{children:"Courageous enough to reject dishonest instructions."}),"\n",(0,a.jsx)(n.li,{children:"Careful not to misuse legal knowledge."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The advocate\u2019s duty is not to win a case by every possible means. The lawyer must pursue the client\u2019s lawful interests without misleading the court or assisting fraud. Character is therefore an essential part of professional equipment, not an optional personal virtue."}),"\n",(0,a.jsx)(n.h3,{id:"4-industry-and-hard-work",children:"4. Industry and Hard Work"}),"\n",(0,a.jsx)(n.p,{children:"The legal profession requires continuous and intensive work. A lawyer must read, investigate, prepare and think about cases repeatedly. Natural intelligence or eloquence cannot replace industry."}),"\n",(0,a.jsx)(n.p,{children:"Hard work involves:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Studying legal texts and law reports."}),"\n",(0,a.jsx)(n.li,{children:"Examining the facts and documents of each case."}),"\n",(0,a.jsx)(n.li,{children:"Preparing witnesses and arguments."}),"\n",(0,a.jsx)(n.li,{children:"Anticipating the opponent\u2019s case."}),"\n",(0,a.jsx)(n.li,{children:"Keeping up with developments in law."}),"\n",(0,a.jsx)(n.li,{children:"Revising and improving one\u2019s arguments."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Aiyar refers to the example of Mr. S. Srinivasa Iyengar to illustrate the importance of extraordinary preparation and sustained effort. The lesson is that professional excellence is normally the result of disciplined work rather than talent alone."}),"\n",(0,a.jsx)(n.h3,{id:"5-the-seven-lamps-of-advocacy",children:"5. The Seven Lamps of Advocacy"}),"\n",(0,a.jsx)(n.p,{children:"The chapter refers to Justice Edward Abbott Parry\u2019s Seven Lamps of Advocacy. These qualities are:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Honesty"})," \u2014 The foundation of the lawyer\u2019s character and reputation."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Courage"})," \u2014 The strength to face the court, the opponent and difficult situations fearlessly."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Industry"})," \u2014 Persistent preparation and hard work."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Wit"})," \u2014 Quick understanding and the ability to respond intelligently."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Eloquence"})," \u2014 The capacity to express arguments clearly and persuasively."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Judgment"})," \u2014 The ability to distinguish important points from unimportant ones and choose the correct course."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Fellowship"})," \u2014 Courtesy, cooperation and professional goodwill towards colleagues."]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"These qualities must work together. Eloquence without knowledge is weak, knowledge without judgment is ineffective and courage without honesty can become recklessness."}),"\n",(0,a.jsx)(n.h3,{id:"6-tact-as-an-additional-quality",children:"6. Tact as an Additional Quality"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar treats tact as an eighth lamp of advocacy. Tact means the ability to deal with people and situations carefully, respectfully and intelligently."}),"\n",(0,a.jsx)(n.p,{children:"A tactful advocate knows:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"When to speak and when to remain silent."}),"\n",(0,a.jsx)(n.li,{children:"Which point should be emphasised."}),"\n",(0,a.jsx)(n.li,{children:"How to question a witness without unnecessary hostility."}),"\n",(0,a.jsx)(n.li,{children:"How to disagree with a judge respectfully."}),"\n",(0,a.jsx)(n.li,{children:"How to advise a client realistically."}),"\n",(0,a.jsx)(n.li,{children:"How to maintain professional relations with the opponent."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Tact does not mean dishonesty or manipulation. It is the practical wisdom that allows a lawyer to use learning, courage and eloquence effectively."}),"\n",(0,a.jsx)(n.h3,{id:"central-message-1",children:"Central Message"}),"\n",(0,a.jsx)(n.p,{children:"The chapter teaches that the complete equipment of a lawyer is a combination of intellectual ability, ethical character and practical skill. The advocate must study law deeply, develop broad knowledge, work continuously, maintain integrity and cultivate the qualities represented by the Seven Lamps of Advocacy."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"chapter-iii-hints-for-law-studies",children:"Chapter III: Hints for Law Studies"}),"\n",(0,a.jsxs)(n.p,{children:["The title of Chapter III is \u201CHints for Law Studies\u201D\u2014not \u201CHinds for Law Studies.\u201D In this chapter of ",(0,a.jsx)(n.em,{children:"Professional Conduct and Advocacy"}),", K. V. Krishnaswami Aiyar gives practical advice to law students and young advocates on how to study law effectively and develop useful professional knowledge."]}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://ia801404.archive.org/25/items/in.ernet.dli.2015.212338/2015.212338.Professional-Conduct_text.pdf",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"1-law-is-a-vast-science",children:"1. Law Is a Vast Science"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar begins by stating that law is an extensive and constantly developing subject. No lawyer can know every part of it completely. As a person studies law more deeply, they become more conscious of the areas that still require study."}),"\n",(0,a.jsx)(n.p,{children:"Therefore, a student should not be overconfident after passing examinations or reading a few textbooks. Legal education is only the beginning of professional learning."}),"\n",(0,a.jsx)(n.h3,{id:"2-study-law-do-not-merely-read-it",children:"2. Study Law, Do Not Merely Read It"}),"\n",(0,a.jsx)(n.p,{children:"The author makes an important distinction between reading law and studying law. Reading means passing through the pages of a book, while studying requires careful understanding, analysis and retention."}),"\n",(0,a.jsx)(n.p,{children:"A student should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Study legal rules with precision."}),"\n",(0,a.jsx)(n.li,{children:"Understand the exact limits of each principle."}),"\n",(0,a.jsx)(n.li,{children:"Avoid vague or inaccurate knowledge."}),"\n",(0,a.jsx)(n.li,{children:"Ask how a rule applies to particular facts."}),"\n",(0,a.jsx)(n.li,{children:"Examine both the argument supporting a proposition and the argument against it."}),"\n",(0,a.jsx)(n.li,{children:"Develop the habit of questioning and investigation."}),"\n"]}),"\n",(0,a.jsxs)(n.p,{children:["Aiyar advises the student to act as a ",(0,a.jsx)(n.em,{children:"prativadi"}),", or opponent, against their own argument. This means examining one\u2019s own conclusion from the opposite side before presenting it in court."]}),"\n",(0,a.jsx)(n.h3,{id:"3-repetition-and-memory",children:"3. Repetition and Memory"}),"\n",(0,a.jsx)(n.p,{children:"Law must be studied repeatedly. Reading a provision once or twice does not mean that it has been properly understood. Repeated study gradually improves accuracy and strengthens memory."}),"\n",(0,a.jsx)(n.p,{children:"However, the author does not recommend mechanical memorisation. Useful legal memory is the ability to:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Recall a principle when required."}),"\n",(0,a.jsx)(n.li,{children:"Understand its proper context."}),"\n",(0,a.jsx)(n.li,{children:"Connect it with related provisions and decisions."}),"\n",(0,a.jsx)(n.li,{children:"Apply it to the facts of a case."}),"\n",(0,a.jsx)(n.li,{children:"Locate the relevant authority quickly."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should organise legal knowledge through classification and association. Properly arranged knowledge is more useful than a large collection of disconnected cases."}),"\n",(0,a.jsx)(n.h3,{id:"4-make-systematic-notes",children:"4. Make Systematic Notes"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar advises students to make notes of new ideas, important principles and useful cases. These notes should be:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Clear."}),"\n",(0,a.jsx)(n.li,{children:"Short."}),"\n",(0,a.jsx)(n.li,{children:"Properly classified."}),"\n",(0,a.jsx)(n.li,{children:"Arranged under suitable subjects."}),"\n",(0,a.jsx)(n.li,{children:"Written in a way that makes future reference easy."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Unorganised notes may create confusion instead of helping the student. Preparing case headnotes and recording the principle decided in a judgment can improve both understanding and memory."}),"\n",(0,a.jsx)(n.h3,{id:"5-study-with-an-enquiring-mind",children:"5. Study with an Enquiring Mind"}),"\n",(0,a.jsx)(n.p,{children:"The student should cultivate a spirit of research and should not accept every statement without examination. This does not mean that a lawyer must remain permanently uncertain. Rather, the lawyer should investigate a proposition carefully before confidently presenting it."}),"\n",(0,a.jsx)(n.p,{children:"While studying a case, the student should ask:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"What principle was decided?"}),"\n",(0,a.jsx)(n.li,{children:"What earlier law did the decision change or explain?"}),"\n",(0,a.jsx)(n.li,{children:"Was the rule limited to particular facts?"}),"\n",(0,a.jsx)(n.li,{children:"Are there exceptions?"}),"\n",(0,a.jsx)(n.li,{children:"How have later courts treated the decision?"}),"\n",(0,a.jsx)(n.li,{children:"What argument could be made against it?"}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"This method develops legal reasoning instead of mere information-based learning."}),"\n",(0,a.jsx)(n.h3,{id:"6-study-through-actual-cases",children:"6. Study Through Actual Cases"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar recommends that lawyers use the preparation of actual cases as an opportunity for serious study. When a client brings a matter involving a particular branch of law, the advocate should not be satisfied with finding one or two authorities."}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should study:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"The history and development of that branch of law."}),"\n",(0,a.jsx)(n.li,{children:"Important statutory provisions."}),"\n",(0,a.jsx)(n.li,{children:"Leading textbooks."}),"\n",(0,a.jsx)(n.li,{children:"Earlier and later judicial decisions."}),"\n",(0,a.jsx)(n.li,{children:"Related principles and exceptions."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Thorough study of one subject in connection with a real case builds confidence and gradually creates a strong foundation of legal knowledge."}),"\n",(0,a.jsx)(n.h3,{id:"7-use-leisure-for-legal-learning",children:"7. Use Leisure for Legal Learning"}),"\n",(0,a.jsx)(n.p,{children:"The author advises young lawyers to use their available time productively. Instead of spending all leisure time on light reading, they should keep useful law books available and read them regularly."}),"\n",(0,a.jsx)(n.p,{children:"He suggests reading standard works on subjects such as:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Contracts."}),"\n",(0,a.jsx)(n.li,{children:"Equity."}),"\n",(0,a.jsx)(n.li,{children:"Partnership."}),"\n",(0,a.jsx)(n.li,{children:"Trusts."}),"\n",(0,a.jsx)(n.li,{children:"Wills."}),"\n",(0,a.jsx)(n.li,{children:"Legal maxims."}),"\n",(0,a.jsx)(n.li,{children:"Charities and other specialised areas."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The objective is not to read every book completely but to become familiar with important legal principles and authoritative texts."}),"\n",(0,a.jsx)(n.h3,{id:"8-read-law-reports-and-use-legal-language",children:"8. Read Law Reports and Use Legal Language"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar gives special importance to reading judgments and law reports. He recommends studying decisions of the House of Lords and the Privy Council, even when a particular case does not directly concern Indian law."}),"\n",(0,a.jsx)(n.p,{children:"Such reading helps a lawyer to:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Understand judicial reasoning."}),"\n",(0,a.jsx)(n.li,{children:"Improve the ability to distinguish cases."}),"\n",(0,a.jsx)(n.li,{children:"Broaden legal understanding."}),"\n",(0,a.jsx)(n.li,{children:"Learn accurate legal phraseology."}),"\n",(0,a.jsx)(n.li,{children:"Develop a strong professional vocabulary."}),"\n",(0,a.jsx)(n.li,{children:"Discover new approaches to legal problems."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A lawyer should learn the language of law because legal expression often conveys a precise meaning that ordinary words cannot fully communicate."}),"\n",(0,a.jsx)(n.h3,{id:"9-know-the-law-library-and-law-reports",children:"9. Know the Law Library and Law Reports"}),"\n",(0,a.jsx)(n.p,{children:"A lawyer need not own a large library merely for appearance. Books are valuable only when they are actually used. Before purchasing books, a student should know:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Which standard books exist."}),"\n",(0,a.jsx)(n.li,{children:"Who wrote them."}),"\n",(0,a.jsx)(n.li,{children:"What subject each book covers."}),"\n",(0,a.jsx)(n.li,{children:"Which books are authoritative."}),"\n",(0,a.jsx)(n.li,{children:"Which law reports contain relevant decisions."}),"\n",(0,a.jsx)(n.li,{children:"How cases are cited and located."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should also understand the system of law reporting and become familiar with the citation of Indian, English and older reports. This makes legal research faster and more reliable."}),"\n",(0,a.jsx)(n.h3,{id:"10-important-branches-of-law-and-procedure",children:"10. Important Branches of Law and Procedure"}),"\n",(0,a.jsx)(n.p,{children:"The chapter emphasises that a practising lawyer must know more than the principal subject studied for examinations. Aiyar particularly stresses the importance of the Indian Evidence Act and its practical application in court."}),"\n",(0,a.jsx)(n.p,{children:"He also advises lawyers to study or become familiar with:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"The Limitation Act."}),"\n",(0,a.jsx)(n.li,{children:"Insolvency law."}),"\n",(0,a.jsx)(n.li,{children:"Company law."}),"\n",(0,a.jsx)(n.li,{children:"Registration law."}),"\n",(0,a.jsx)(n.li,{children:"Stamp law."}),"\n",(0,a.jsx)(n.li,{children:"Suits Valuation law."}),"\n",(0,a.jsx)(n.li,{children:"Court-fees law."}),"\n",(0,a.jsx)(n.li,{children:"Applicable court rules."}),"\n",(0,a.jsx)(n.li,{children:"Civil court manuals."}),"\n",(0,a.jsx)(n.li,{children:"Relevant unrepealed statutes."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"This practical knowledge is especially important for lawyers conducting litigation in trial courts. The advocate should be capable of performing the essential work that might otherwise be left entirely to a clerk."}),"\n",(0,a.jsx)(n.h3,{id:"central-message-2",children:"Central Message"}),"\n",(0,a.jsx)(n.p,{children:"The chapter\u2019s central message is that legal education must be continuous, practical and systematic. A good lawyer studies law deeply, revises it repeatedly, researches with curiosity, keeps organised notes, reads judgments and remains familiar with statutes, reports and court rules."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"chapter-iv-training-grounds",children:"Chapter IV: Training Grounds"}),"\n",(0,a.jsx)(n.p,{children:"In Chapter IV, \u201CTraining Grounds,\u201D K. V. Krishnaswami Aiyar explains where and how a young lawyer should obtain practical training. He identifies two principal training grounds: the chambers of a senior practitioner and the court-house."}),"\n",(0,a.jsx)(n.p,{children:"Legal education in books is necessary, but practical experience is essential for learning the actual work, traditions and discipline of advocacy."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://www.sci.gov.in/lawyers-chamber-allotment/",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"1-attend-the-chambers-of-a-senior",children:"1. Attend the Chambers of a Senior"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar strongly advises every young lawyer to work in the chambers of an experienced senior. He refers to the traditional view that a young lawyer learns the practical \u201Cmechanism\u201D of legal work by observing a skilled practitioner."}),"\n",(0,a.jsx)(n.p,{children:"Working in a senior\u2019s chamber helps a beginner to:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Become familiar with the atmosphere of the legal profession."}),"\n",(0,a.jsx)(n.li,{children:"Observe how cases are received, studied and prepared."}),"\n",(0,a.jsx)(n.li,{children:"Learn how pleadings and other legal documents are drafted."}),"\n",(0,a.jsx)(n.li,{children:"Understand how legal research is conducted."}),"\n",(0,a.jsx)(n.li,{children:"Learn the preparation of briefs and arguments."}),"\n",(0,a.jsx)(n.li,{children:"Observe the examination and cross-examination of witnesses."}),"\n",(0,a.jsx)(n.li,{children:"Discuss legal problems with experienced lawyers."}),"\n",(0,a.jsx)(n.li,{children:"Understand the traditions and etiquette of the Bar."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The purpose of working with a senior is not to remain dependent forever. It is a preparatory stage through which a young lawyer develops the confidence and ability to stand independently."}),"\n",(0,a.jsx)(n.h3,{id:"2-put-forth-the-best-effort",children:"2. Put Forth the Best Effort"}),"\n",(0,a.jsx)(n.p,{children:"A young lawyer should work in the senior\u2019s chamber with complete sincerity. Even when the work is difficult or unpaid, it should be performed carefully and thoroughly."}),"\n",(0,a.jsx)(n.p,{children:"The junior should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Study every assigned case seriously."}),"\n",(0,a.jsx)(n.li,{children:"Read the pleadings and documents completely."}),"\n",(0,a.jsx)(n.li,{children:"Search for relevant authorities."}),"\n",(0,a.jsx)(n.li,{children:"Prepare useful notes."}),"\n",(0,a.jsx)(n.li,{children:"Think of both sides of the case."}),"\n",(0,a.jsx)(n.li,{children:"Offer constructive suggestions to the senior."}),"\n",(0,a.jsx)(n.li,{children:"Complete work within the required time."}),"\n",(0,a.jsx)(n.li,{children:"Avoid doing work mechanically or carelessly."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A junior can build a good professional reputation by making genuine efforts. A senior will value an assistant who is dependable, hardworking and capable of producing useful legal ideas."}),"\n",(0,a.jsx)(n.h3,{id:"3-learn-through-observation-and-discussion",children:"3. Learn Through Observation and Discussion"}),"\n",(0,a.jsx)(n.p,{children:"The chamber provides an opportunity to learn through direct observation. A young lawyer should listen carefully to discussions between seniors, juniors, clients and other lawyers."}),"\n",(0,a.jsx)(n.p,{children:"The junior should not hesitate to ask questions at the appropriate time. Discussion helps the student understand:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"How legal issues are identified."}),"\n",(0,a.jsx)(n.li,{children:"How facts are separated from irrelevant details."}),"\n",(0,a.jsx)(n.li,{children:"How authorities are selected."}),"\n",(0,a.jsx)(n.li,{children:"How arguments are arranged."}),"\n",(0,a.jsx)(n.li,{children:"How a lawyer gives practical advice to a client."}),"\n",(0,a.jsx)(n.li,{children:"How professional decisions are made."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Aiyar\u2019s advice encourages active learning rather than passive attendance. The young lawyer should observe, think, prepare and gradually participate in the work."}),"\n",(0,a.jsx)(n.h3,{id:"4-show-professional-qualities",children:"4. Show Professional Qualities"}),"\n",(0,a.jsx)(n.p,{children:"While working in a senior\u2019s chamber, a young lawyer should cultivate professional discipline and good relationships. Aiyar emphasises respect for seniors, sympathy towards juniors and cooperation with fellow members of the profession."}),"\n",(0,a.jsx)(n.p,{children:"The important qualities include:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Punctuality."}),"\n",(0,a.jsx)(n.li,{children:"Respectful conduct."}),"\n",(0,a.jsx)(n.li,{children:"Patience."}),"\n",(0,a.jsx)(n.li,{children:"Courtesy."}),"\n",(0,a.jsx)(n.li,{children:"Confidentiality."}),"\n",(0,a.jsx)(n.li,{children:"Willingness to help."}),"\n",(0,a.jsx)(n.li,{children:"Absence of jealousy."}),"\n",(0,a.jsx)(n.li,{children:"Readiness to acknowledge assistance received from others."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A lawyer should not be selfish or treat colleagues merely as competitors. The Bar is a professional community, and its dignity depends on mutual respect and cooperation."}),"\n",(0,a.jsx)(n.h3,{id:"5-the-court-house-as-a-training-ground",children:"5. The Court-House as a Training Ground"}),"\n",(0,a.jsx)(n.p,{children:"The second major training ground is the court-house. Aiyar advises young lawyers not to stay away from court merely because they have no case to conduct on a particular day."}),"\n",(0,a.jsx)(n.p,{children:"They should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Attend court regularly."}),"\n",(0,a.jsx)(n.li,{children:"Be properly dressed and disciplined."}),"\n",(0,a.jsx)(n.li,{children:"Observe proceedings carefully."}),"\n",(0,a.jsx)(n.li,{children:"Watch how experienced lawyers argue."}),"\n",(0,a.jsx)(n.li,{children:"Study the judge\u2019s approach to facts and law."}),"\n",(0,a.jsx)(n.li,{children:"Observe the examination of witnesses."}),"\n",(0,a.jsx)(n.li,{children:"Notice how objections are raised and decided."}),"\n",(0,a.jsx)(n.li,{children:"Learn courtroom manners and procedure."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Regular attendance helps a young lawyer become familiar with the court environment and overcome initial nervousness. It also teaches lessons that cannot be learnt fully from books."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://archive.org/stream/professionalcond029273mbp/professionalcond029273mbp_djvu.txt",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"6-learn-from-trials",children:"6. Learn from Trials"}),"\n",(0,a.jsx)(n.p,{children:"A careful study of a trial from beginning to end is a valuable legal education. By observing actual proceedings, the young lawyer can learn:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"How a case is called and conducted."}),"\n",(0,a.jsx)(n.li,{children:"How pleadings are used during argument."}),"\n",(0,a.jsx)(n.li,{children:"How evidence is introduced."}),"\n",(0,a.jsx)(n.li,{children:"How witnesses respond to questions."}),"\n",(0,a.jsx)(n.li,{children:"How cross-examination exposes weaknesses."}),"\n",(0,a.jsx)(n.li,{children:"How judges react to legal and factual arguments."}),"\n",(0,a.jsx)(n.li,{children:"How advocates deal with unexpected developments."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Aiyar also advises young lawyers to learn from the mistakes of others. Observing a poorly prepared case, an ineffective argument or improper courtroom conduct can teach valuable lessons about what should be avoided."}),"\n",(0,a.jsx)(n.h3,{id:"7-use-special-opportunities",children:"7. Use Special Opportunities"}),"\n",(0,a.jsx)(n.p,{children:"Presence in court may create opportunities for a young lawyer to become known to seniors, judges and members of the Bar. Such opportunities should be used through ability and hard work, not through improper self-promotion."}),"\n",(0,a.jsx)(n.p,{children:"A young lawyer may distinguish themselves by:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Being prepared with the facts of a case."}),"\n",(0,a.jsx)(n.li,{children:"Knowing the relevant legal authorities."}),"\n",(0,a.jsx)(n.li,{children:"Giving a short but accurate answer when asked."}),"\n",(0,a.jsx)(n.li,{children:"Assisting a senior effectively."}),"\n",(0,a.jsx)(n.li,{children:"Presenting a useful point at the proper time."}),"\n",(0,a.jsx)(n.li,{children:"Showing reliability and professional courtesy."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Aiyar cautions, in substance, that merely collecting many case citations is not enough. An authority should be relevant, understood and persuasively connected with the facts of the case."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://archive.org/stream/professionalcond029273mbp/professionalcond029273mbp_djvu.txt",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"central-message-3",children:"Central Message"}),"\n",(0,a.jsx)(n.p,{children:"The chapter teaches that a young lawyer is trained through practical exposure, observation and disciplined service. A senior\u2019s chamber teaches the methods of legal work, while the court-house teaches the realities of advocacy and judicial proceedings."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"chapter-v-meeting-clients",children:"Chapter V: Meeting Clients"}),"\n",(0,a.jsx)(n.p,{children:"In Chapter V, \u201CMeeting Clients,\u201D K. V. Krishnaswami Aiyar explains how a lawyer should receive, interview and advise a client. The chapter emphasises sympathy, patience, careful investigation, independent judgment, confidence and fair settlement of fees."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://archive.org/stream/professionalcond029273mbp/professionalcond029273mbp_djvu.txt",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"1-receive-the-client-with-kindness",children:"1. Receive the Client with Kindness"}),"\n",(0,a.jsx)(n.p,{children:"A client usually approaches a lawyer because of anxiety, difficulty or fear. The lawyer should therefore receive the client courteously and create an atmosphere of trust."}),"\n",(0,a.jsx)(n.p,{children:"Aiyar advises the advocate to:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Receive the client with kindness."}),"\n",(0,a.jsx)(n.li,{children:"Listen patiently and sympathetically."}),"\n",(0,a.jsx)(n.li,{children:"Allow the client to explain the entire matter."}),"\n",(0,a.jsx)(n.li,{children:"Avoid interrupting or insulting the client."}),"\n",(0,a.jsx)(n.li,{children:"Permit the client to repeat facts if necessary."}),"\n",(0,a.jsx)(n.li,{children:"Give the client confidence that the matter is being taken seriously."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The client may not know which facts are legally important. Therefore, the lawyer should first listen fully and then ask suitable questions."}),"\n",(0,a.jsx)(n.h3,{id:"2-make-careful-inquiries",children:"2. Make Careful Inquiries"}),"\n",(0,a.jsx)(n.p,{children:"After hearing the client\u2019s version, the lawyer must investigate the facts independently. The advocate should not prepare a case merely on the client\u2019s first statement."}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should inquire about:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"The complete history of the dispute."}),"\n",(0,a.jsx)(n.li,{children:"The persons involved."}),"\n",(0,a.jsx)(n.li,{children:"Relevant dates and events."}),"\n",(0,a.jsx)(n.li,{children:"Documents and correspondence."}),"\n",(0,a.jsx)(n.li,{children:"Previous proceedings or settlements."}),"\n",(0,a.jsx)(n.li,{children:"Witnesses who can support the client."}),"\n",(0,a.jsx)(n.li,{children:"Possible facts that may harm the client\u2019s case."}),"\n",(0,a.jsx)(n.li,{children:"The remedy that the client actually wants."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A proper inquiry helps the advocate discover the real nature of the dispute and prevents errors caused by incomplete information."}),"\n",(0,a.jsx)(n.h3,{id:"3-do-not-believe-everything-blindly",children:"3. Do Not Believe Everything Blindly"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar warns lawyers not to accept every statement made by a client without verification. A client may unintentionally omit facts, misunderstand the law or deliberately conceal an inconvenient circumstance."}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should therefore:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Compare the client\u2019s statements with documents."}),"\n",(0,a.jsx)(n.li,{children:"Ask questions from different angles."}),"\n",(0,a.jsx)(n.li,{children:"Look for contradictions."}),"\n",(0,a.jsx)(n.li,{children:"Verify important facts where possible."}),"\n",(0,a.jsx)(n.li,{children:"Identify both favourable and unfavourable circumstances."}),"\n",(0,a.jsx)(n.li,{children:"Avoid giving advice before understanding the entire case."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"This does not mean that the lawyer should treat every client as dishonest. It means that professional judgment must be based on verified facts rather than blind confidence."}),"\n",(0,a.jsx)(n.h3,{id:"4-inspire-confidence-through-conduct",children:"4. Inspire Confidence Through Conduct"}),"\n",(0,a.jsx)(n.p,{children:"A lawyer\u2019s conduct should inspire confidence in the client. Confidence is created not by exaggerated promises but by calm, clear and honest behaviour."}),"\n",(0,a.jsx)(n.p,{children:"The advocate should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Speak clearly and respectfully."}),"\n",(0,a.jsx)(n.li,{children:"Explain the legal position in language the client understands."}),"\n",(0,a.jsx)(n.li,{children:"Avoid unnecessary technical expressions."}),"\n",(0,a.jsx)(n.li,{children:"Maintain confidentiality."}),"\n",(0,a.jsx)(n.li,{children:"Be punctual and accessible."}),"\n",(0,a.jsx)(n.li,{children:"Give realistic advice."}),"\n",(0,a.jsx)(n.li,{children:"Avoid promising a certain result."}),"\n",(0,a.jsx)(n.li,{children:"Inform the client about difficulties and risks."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The lawyer must not create false hope by claiming that victory is guaranteed. Honest advice, even when unfavourable, is more valuable than comforting but misleading assurances."}),"\n",(0,a.jsx)(n.h3,{id:"5-offering-opinions-and-advice",children:"5. Offering Opinions and Advice"}),"\n",(0,a.jsx)(n.p,{children:"Before giving an opinion, the lawyer should make sure that the facts have been sufficiently investigated and the relevant law has been studied. An opinion should be based on reasoned analysis rather than instinct or a desire to please the client."}),"\n",(0,a.jsx)(n.p,{children:"A proper legal opinion should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"State the material facts."}),"\n",(0,a.jsx)(n.li,{children:"Identify the legal issue."}),"\n",(0,a.jsx)(n.li,{children:"Explain the applicable law."}),"\n",(0,a.jsx)(n.li,{children:"Mention relevant authorities where necessary."}),"\n",(0,a.jsx)(n.li,{children:"Point out the strengths and weaknesses of the case."}),"\n",(0,a.jsx)(n.li,{children:"Explain possible remedies and risks."}),"\n",(0,a.jsx)(n.li,{children:"Give a practical recommendation."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should not encourage litigation merely because the client is willing to pay. If the case is weak, dishonest or legally unsustainable, the advocate should advise the client accordingly."}),"\n",(0,a.jsx)(n.h3,{id:"6-fixing-the-fee",children:"6. Fixing the Fee"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar gives practical guidance about settling professional fees. The fee should be discussed and settled at the earliest reasonable opportunity. This avoids later misunderstanding between the lawyer and the client."}),"\n",(0,a.jsx)(n.p,{children:"The guiding principles are:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Do not make the fee the sole consideration in deciding whether to assist."}),"\n",(0,a.jsx)(n.li,{children:"Do not charge an oppressive fee."}),"\n",(0,a.jsx)(n.li,{children:"Do not undervalue professional services merely to obtain work."}),"\n",(0,a.jsx)(n.li,{children:"Consider the nature and difficulty of the case."}),"\n",(0,a.jsx)(n.li,{children:"Consider the time and labour required."}),"\n",(0,a.jsx)(n.li,{children:"Consider the importance of the matter and the client\u2019s circumstances."}),"\n",(0,a.jsx)(n.li,{children:"Make the terms of payment clear."}),"\n",(0,a.jsx)(n.li,{children:"Record the arrangement whenever possible."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Aiyar\u2019s advice may be summarised as follows: the fee should be fair to both sides. The lawyer should neither exploit the client nor reduce professional work to a mere competition for the lowest fee."}),"\n",(0,a.jsx)(n.h3,{id:"7-treat-poor-clients-fairly",children:"7. Treat Poor Clients Fairly"}),"\n",(0,a.jsx)(n.p,{children:"The author does not support rejecting a deserving case solely because the client is unable to pay a substantial fee. A lawyer should consider whether the case is meritorious and whether there is a proper reason for accepting or refusing it."}),"\n",(0,a.jsx)(n.p,{children:"This does not mean that every advocate must accept every unpaid case. It means that poverty alone should not be treated as proof that a client has no right to legal assistance. The professional duty to justice should sometimes influence the lawyer\u2019s decision."}),"\n",(0,a.jsx)(n.h3,{id:"central-message-4",children:"Central Message"}),"\n",(0,a.jsx)(n.p,{children:"The chapter teaches that the first meeting with a client is both a professional and ethical responsibility. A lawyer must listen with sympathy, investigate carefully, maintain independence, give honest advice and settle fees fairly."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"chapter-vi-the-preparation-of-a-case",children:"Chapter VI: The Preparation of a Case"}),"\n",(0,a.jsxs)(n.p,{children:["Chapter VI of ",(0,a.jsx)(n.em,{children:"Professional Conduct and Advocacy"})," by K. V. Krishnaswami Aiyar explains how an advocate should prepare a case before presenting it in court. The author compares litigation to warfare, where success depends not only on courage or speaking ability but also on careful strategy, accurate information, preparation of evidence and anticipation of the opponent\u2019s moves."]}),"\n",(0,a.jsx)(n.p,{children:"The chapter covers preparation for both trial proceedings and appellate hearings."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.a,{href:"https://ia801404.us.archive.org/25/items/in.ernet.dli.2015.212338/2015.212338.Professional-Conduct_text.pdf",children:"Source"})}),"\n",(0,a.jsx)(n.h3,{id:"1-form-a-clear-plan",children:"1. Form a Clear Plan"}),"\n",(0,a.jsx)(n.p,{children:"The first duty of an advocate is to form a complete plan of the case. The advocate should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Understand the client\u2019s story fully."}),"\n",(0,a.jsx)(n.li,{children:"Separate relevant facts from irrelevant details."}),"\n",(0,a.jsx)(n.li,{children:"Identify the strengths and weaknesses of both sides."}),"\n",(0,a.jsx)(n.li,{children:"Arrange the facts in chronological order."}),"\n",(0,a.jsx)(n.li,{children:"Decide what facts must be proved and how they will be proved."}),"\n",(0,a.jsx)(n.li,{children:"Anticipate the arguments and objections of the opposite party."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A good lawyer must possess a strong selective faculty\u2014the ability to select important facts and reject unnecessary material. At the same time, the lawyer must have an eye for small details because apparently minor facts may become important during examination or argument."}),"\n",(0,a.jsx)(n.h3,{id:"2-study-the-documents-and-investigate-the-facts",children:"2. Study the Documents and Investigate the Facts"}),"\n",(0,a.jsx)(n.p,{children:"The advocate should carefully examine every document connected with the case. Merely listening to the client is not sufficient; the lawyer must verify the client\u2019s statements by studying records and making necessary inquiries."}),"\n",(0,a.jsx)(n.p,{children:"The documents should be:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Collected from both the client and other relevant sources."}),"\n",(0,a.jsx)(n.li,{children:"Arranged in chronological order."}),"\n",(0,a.jsx)(n.li,{children:"Compared with the pleadings and the opponent\u2019s documents."}),"\n",(0,a.jsx)(n.li,{children:"Listed carefully, with the witnesses connected to each document noted."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The author stresses that the lawyer must prepare the case on the basis of facts rather than blindly accepting the client\u2019s version. Proper preparation also involves local inspection, obtaining information from persons who know the facts and examining the surrounding circumstances."}),"\n",(0,a.jsx)(n.h3,{id:"3-study-the-law-thoroughly",children:"3. Study the Law Thoroughly"}),"\n",(0,a.jsx)(n.p,{children:"Only after understanding the facts should the advocate study the law. Aiyar advises lawyers not to look merely for isolated authorities through an index. Instead, they should study the relevant chapter, statute or legal principle as a whole."}),"\n",(0,a.jsx)(n.p,{children:"The advocate should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Read the complete statutory provision."}),"\n",(0,a.jsx)(n.li,{children:"Examine related provisions."}),"\n",(0,a.jsx)(n.li,{children:"Study leading cases carefully."}),"\n",(0,a.jsx)(n.li,{children:"Trace a decision backwards to discover the authorities on which it is based."}),"\n",(0,a.jsx)(n.li,{children:"Trace it forwards to see how later courts have treated it."}),"\n",(0,a.jsx)(n.li,{children:"Consult digests and legal dictionaries."}),"\n",(0,a.jsx)(n.li,{children:"Read full judgments rather than relying only on headnotes."}),"\n",(0,a.jsx)(n.li,{children:"Look for authorities dealing with possible side issues."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The underlying lesson is that a lawyer must not depend upon superficial research. Legal preparation must be exhaustive because an opponent or judge may raise an issue that the advocate initially considered unimportant."}),"\n",(0,a.jsx)(n.h3,{id:"4-prepare-for-the-trial",children:"4. Prepare for the Trial"}),"\n",(0,a.jsx)(n.p,{children:"In an original trial, the advocate should use all lawful procedural methods available for discovering and establishing the truth. This may include interrogatories, discovery of documents, inspection and commissions."}),"\n",(0,a.jsx)(n.p,{children:"The advocate\u2019s preparation should aim at two objectives:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsx)(n.li,{children:"Constructing the client\u2019s own case through pleadings, documents and witnesses."}),"\n",(0,a.jsx)(n.li,{children:"Shattering the opponent\u2019s case by exposing contradictions, omissions, weaknesses and lack of evidence."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The author does not mean that advocacy should become unfair or dishonest. The opponent\u2019s case must be challenged through proper legal methods and reliable evidence."}),"\n",(0,a.jsx)(n.h3,{id:"5-prepare-the-evidence-and-witnesses",children:"5. Prepare the Evidence and Witnesses"}),"\n",(0,a.jsx)(n.p,{children:"Witness preparation is a major part of case preparation. The advocate should take a proper proof or statement from each witness beforehand. This helps the lawyer understand:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"What the witness actually knows."}),"\n",(0,a.jsx)(n.li,{children:"Which facts the witness can prove."}),"\n",(0,a.jsx)(n.li,{children:"Whether the witness supports or weakens the case."}),"\n",(0,a.jsx)(n.li,{children:"Whether the witness has made earlier contradictory statements."}),"\n",(0,a.jsx)(n.li,{children:"How the witness is likely to behave in court."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should also observe the demeanour of witnesses\u2014whether they appear confident, hesitant, evasive or unreliable. However, the advocate should not call every available witness merely to increase the number of witnesses. A witness who is unnecessary, unreliable or likely to damage the case may be better left unexamined."}),"\n",(0,a.jsx)(n.p,{children:"The evidence must be complete enough to satisfy legal and procedural requirements. Formal defects in proof can weaken an otherwise strong case."}),"\n",(0,a.jsx)(n.h3,{id:"6-prepare-for-cross-examination",children:"6. Prepare for Cross-Examination"}),"\n",(0,a.jsx)(n.p,{children:"Cross-examination should not be conducted randomly. Before entering court, the advocate should prepare the important questions and decide what facts must be obtained from the opponent\u2019s witnesses."}),"\n",(0,a.jsx)(n.p,{children:"The purposes of cross-examination include:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Eliciting facts favourable to the client."}),"\n",(0,a.jsx)(n.li,{children:"Testing the accuracy of the witness\u2019s memory."}),"\n",(0,a.jsx)(n.li,{children:"Showing contradictions in the witness\u2019s testimony."}),"\n",(0,a.jsx)(n.li,{children:"Establishing bias, interest or lack of knowledge."}),"\n",(0,a.jsx)(n.li,{children:"Proving the advocate\u2019s version of the case."}),"\n",(0,a.jsx)(n.li,{children:"Weakening the opponent\u2019s evidence."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The advocate should keep proper notes and use documents intelligently. Cross-examination is not an opportunity for theatrical performance or personal hostility. It must be controlled, purposeful and connected with the issues in dispute."}),"\n",(0,a.jsx)(n.h3,{id:"7-arrange-papers-properly",children:"7. Arrange Papers Properly"}),"\n",(0,a.jsx)(n.p,{children:"A lawyer\u2019s papers should be arranged so that every document and fact can be found quickly during the hearing. Important materials should be indexed and placed in a logical order."}),"\n",(0,a.jsx)(n.p,{children:"Proper arrangement should include:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Pleadings."}),"\n",(0,a.jsx)(n.li,{children:"Chronological lists of documents."}),"\n",(0,a.jsx)(n.li,{children:"Copies of the client\u2019s documents."}),"\n",(0,a.jsx)(n.li,{children:"Copies of the opponent\u2019s documents."}),"\n",(0,a.jsx)(n.li,{children:"Statements or proofs of witnesses."}),"\n",(0,a.jsx)(n.li,{children:"Relevant statutory provisions."}),"\n",(0,a.jsx)(n.li,{children:"Case-law authorities."}),"\n",(0,a.jsx)(n.li,{children:"Notes of inspections and inquiries."}),"\n",(0,a.jsx)(n.li,{children:"Questions prepared for cross-examination."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Disorganised papers can cause delay, confusion and loss of confidence in court. Good filing and note-making are therefore essential parts of professional competence."}),"\n",(0,a.jsx)(n.h3,{id:"8-preparation-for-appellate-hearings",children:"8. Preparation for Appellate Hearings"}),"\n",(0,a.jsx)(n.p,{children:"Preparation in an appeal follows the same basic principles, but the advocate must pay special attention to the judgment of the lower court."}),"\n",(0,a.jsx)(n.p,{children:"The lawyer should:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Read the judgment repeatedly."}),"\n",(0,a.jsx)(n.li,{children:"Understand the findings on each issue."}),"\n",(0,a.jsx)(n.li,{children:"Examine the reasons given by the lower court."}),"\n",(0,a.jsx)(n.li,{children:"Compare those findings with the pleadings, documents and oral evidence."}),"\n",(0,a.jsx)(n.li,{children:"Study the original record wherever necessary."}),"\n",(0,a.jsx)(n.li,{children:"Identify errors of fact, law, procedure or appreciation of evidence."}),"\n",(0,a.jsx)(n.li,{children:"Prepare complete notes for the argument."}),"\n",(0,a.jsx)(n.li,{children:"Anticipate the respondent\u2019s answer to every ground of appeal."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"An appeal should not be argued merely by repeating the facts or expressing dissatisfaction with the decision. The advocate must demonstrate precisely why the judgment is legally or factually incorrect."}),"\n",(0,a.jsx)(n.h3,{id:"9-rehearse-and-think-repeatedly",children:"9. Rehearse and Think Repeatedly"}),"\n",(0,a.jsx)(n.p,{children:"Aiyar emphasises repeated study and reflection. An advocate should think about the case before the hearing from different angles:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"What is the strongest point?"}),"\n",(0,a.jsx)(n.li,{children:"What is the weakest point?"}),"\n",(0,a.jsx)(n.li,{children:"What questions may the judge ask?"}),"\n",(0,a.jsx)(n.li,{children:"What argument will the opponent make?"}),"\n",(0,a.jsx)(n.li,{children:"How can an adverse authority be distinguished?"}),"\n",(0,a.jsx)(n.li,{children:"What relief should be requested?"}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Rehearsing the argument is not a sign of weakness. It enables the advocate to speak clearly, avoid omissions and answer questions confidently. Even a seemingly simple case must be properly prepared."})]})}function h(e={}){let{wrapper:n}={...(0,t.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453(e,n,i){i.d(n,{R:()=>r,x:()=>l});var s=i(6540);let a={},t=s.createContext(a);function r(e){let n=s.useContext(t);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),s.createElement(t.Provider,{value:n},e.children)}}}]);